export const SEC_META = {
  GS:   { name: "Chapters", icon: "📔", color: "#ff8a7a" },
  QUIZ: { name: "Quiz", icon: "📝", color: "#f59e0b" },
  PYQ:  { name: "Asli PYQ", icon: "🎯", color: "#8ab4f8" },
};
export const PASS_META = [{"pass":1,"name":"Seekhna","days":8},{"pass":2,"name":"Yaad","days":6},{"pass":3,"name":"Pakka","days":5},{"pass":4,"name":"Tez","days":4},{"pass":5,"name":"Flash","days":4},{"pass":6,"name":"Aakhri","days":3}];
export const PASS_COLOR = ["#8ab4f8", "#a78bfa", "#f59e0b", "#fbbf24", "#6bd39a", "#34d399"];

const KEY = "cgl.gs30";
import { storeSet } from "./bigstore";

function read() {
  if (typeof window === "undefined") return { startDate: null, done: {}, weak: {} };
  try {
    const v = JSON.parse(localStorage.getItem(KEY) || "{}");
    return { startDate: v.startDate || null, done: v.done || {}, weak: v.weak || {} };
  } catch {
    return { startDate: null, done: {}, weak: {} };
  }
}
// storeSet se hi likhte hain (localStorage.setItem se nahi): wahi ek jagah hai
// jahan sync ke liye delete ki khabar darj hoti hai.
function write(v) { try { storeSet(KEY, JSON.stringify(v)); } catch { /* quota */ } }

export function getGs30() { return read(); }
export function setStartDate(date) { const v = read(); v.startDate = date; write(v); return v; }
export function resetGs30() { write({ startDate: null, done: {}, weak: {} }); return read(); }

export function toggleItem(day, id) {
  const v = read();
  const d = v.done[day] || (v.done[day] = {});
  if (d[id]) delete d[id]; else d[id] = true;
  write(v);
  return v;
}

// ⭐ weak marks are keyed by book+chapter, NOT by day — a chapter flagged in
// pass 2 must still read as flagged when pass 6 reaches it three weeks later.
export const weakKey = (book, ch) => book + "|" + ch;
export function toggleWeak(book, ch) {
  const v = read();
  const k = weakKey(book, ch);
  if (v.weak[k]) delete v.weak[k]; else v.weak[k] = true;
  write(v);
  return v;
}
export function weakCount(state) { return Object.keys(state.weak || {}).length; }

export function planFor(n) { return DAYS.find((d) => d.day === n) || null; }

// Same dayKey() rollover as the rest of the app (day ends at 02:00).
export function currentDayNum(state = read()) {
  if (!state.startDate) return 0;
  const [y1, m1, d1] = state.startDate.split("-").map(Number);
  const [y2, m2, d2] = dayKey().split("-").map(Number);
  return Math.round((Date.UTC(y2, m2 - 1, d2) - Date.UTC(y1, m1 - 1, d1)) / 864e5) + 1;
}

// A GS block ticks per chapter; a quiz/PYQ block ticks once.
export function slotsOf(b) {
  return b.chapters ? b.chapters.map((_, i) => b.id + "-" + i) : [b.id];
}

export function dayStats(state, n) {
  const p = planFor(n);
  if (!p) return { total: 0, done: 0, mustTotal: 0, mustDone: 0, min: 0, mustMin: 0 };
  const done = state.done[n] || {};
  let total = 0, dn = 0, mustTotal = 0, mustDone = 0, min = 0, mustMin = 0;
  for (const b of p.blocks) {
    min += b.min || 0;
    if (b.must) mustMin += b.min || 0;
    for (const s of slotsOf(b)) {
      total++;
      if (b.must) mustTotal++;
      if (done[s]) { dn++; if (b.must) mustDone++; }
    }
  }
  return { total, done: dn, mustTotal, mustDone, min, mustMin };
}
export function dayCompletion(state, n) {
  const s = dayStats(state, n);
  return s.total ? s.done / s.total : 0;
}
export function mustComplete(state, n) {
  const s = dayStats(state, n);
  return s.mustTotal > 0 && s.mustDone >= s.mustTotal;
}
export function planStreak(state) {
  const cur = Math.min(currentDayNum(state), 30);
  let s = 0;
  if (cur >= 1 && mustComplete(state, cur)) s++;
  for (let i = cur - 1; i >= 1; i--) {
    if (mustComplete(state, i)) s++; else break;
  }
  return s;
}

// Chapters ticked at least once in each of the six passes — the "sab ho jaye" bar.
export function passProgress(state) {
  const out = [0, 0, 0, 0, 0, 0];
  for (const d of DAYS) {
    const done = state.done[d.day] || {};
    for (const b of d.blocks) {
      if (!b.chapters) continue;
      b.chapters.forEach((_, i) => { if (done[b.id + "-" + i]) out[d.pass - 1]++; });
    }
  }
  return out;
}
export const TOTAL_CHAPTERS = 121;
export const TOTAL_PAGES = 511;
export const TOTAL_DAYS = 30;
